"""Re-add modified destination files while retaining their source naming."""
import os
import shutil
import stat

import dump_command
from source_ops import _source_entry, _target_rel


def run(source, destination, args=None, dry_run=False):
    args = list(args or [])
    root = os.path.abspath(os.path.expanduser(destination))
    source = os.path.abspath(os.path.expanduser(source))
    recursive = "--recursive=false" not in args and "-r=false" not in args
    targets = [x for x in args if not x.startswith("-")]
    managed = dump_command.load_targets(source)
    if not targets:
        targets = sorted(managed)
    else:
        selected = []
        for item in targets:
            rel = _target_rel(item, root) if os.path.isabs(os.path.expanduser(item)) else item
            rel = rel.replace(os.sep, "/").removeprefix("./")
            if rel in managed:
                selected.append(rel)
            elif recursive:
                selected.extend(k for k in managed if k.startswith(rel.rstrip("/") + "/"))
        targets = sorted(set(selected))
    errors = []
    for item in targets:
        rel = _target_rel(item, root) if os.path.isabs(os.path.expanduser(item)) else item
        rel = rel.replace(os.sep, "/").removeprefix("./")
        entry = managed.get(rel)
        if not entry or entry.get("type") != "file":
            continue
        srcpath = _source_entry(source, rel)
        if not srcpath or srcpath.endswith(".tmpl"):
            continue
        destpath = os.path.join(root, *rel.split("/"))
        try:
            if not os.path.isfile(destpath) or os.path.islink(destpath):
                continue
            with open(destpath, "rb") as f:
                contents = f.read()
            with open(srcpath, "rb") as f:
                if f.read() == contents:
                    continue
            if not dry_run:
                shutil.copyfile(destpath, srcpath)
        except OSError as e:
            errors.append(f"chezmoi: {e}\n")
    return "", "".join(errors), 1 if errors else 0
